void basic_handler(int sig) {
    if (sig == SIGINT) {
        /* cleanup */
    }
}

// Basic Handler Registration
void register_sigint() {
    signal(SIGINT, basic_handler);
}

// Reset signal action to default
void reset_sigquit() {
    signal(SIGQUIT, SIG_DFL);
}

// Ignore a signal
void ignore_sighup() {
    signal(SIGHUP, SIG_IGN);
}
