struct sigaction sa;

void robust_handler(int sig) { /* ... */ }

void setup_sigterm_robust() {
    // Zero out the structure
    memset(&sa, 0, sizeof(sa));

    sa.sa_handler = robust_handler;
    sigemptyset(&sa.sa_mask); // No signals blocked during execution
    sa.sa_flags = SA_RESTART; // Restart syscalls

    // Install the handler for SIGTERM
    sigaction(SIGTERM, &sa, NULL);
}
