pid_t target_pid = 1234;
int error_check;

// Send SIGKILL to another process
error_check = kill(target_pid, SIGKILL);

// Send signal to self (same as kill(getpid(), SIGUSR2))
error_check = raise(SIGUSR2);

// Pause execution until a signal arrives
pause();
